/* =============================================================================
 * BUILD PROMPT - POVO AI Guidance, Example Notes v1
 *
 * Contract (docs/ARCHITECTURE.md section 6):
 *   request  {request_id, category, category_label, point_text, reception,
 *             other_points:[string], participant:{role_type, display_name,
 *             decile, tier_name, segment_short_name, competitive_focus_label,
 *             hs_patients, povo_patients, jak_patients, povo_discussions,
 *             last_call_date}, interactions:[{date, type_label, summary}],
 *             count, max_chars}
 *   response {ok:true, notes:[string]} | {ok:false, reason}
 *
 * The model PREDICTS what the rep will write; the rep picks one and edits it.
 * Nothing here is approved claim text, so the backend re-checks every note
 * against the compliance rules before it reaches the screen.
 * ========================================================================== */
const body = ($input.first().json || {}).body || {};
const reject = (reason) => [{ json: { valid: false, reason: String(reason).slice(0, 200) } }];
const str = (v) => (v === null || v === undefined ? '' : String(v)).replace(/\s+/g, ' ').trim();

const CATEGORIES = ['messaging', 'objection', 'closing', 'additional'];
const category = str(body.category);
if (!CATEGORIES.includes(category)) return reject('category must be one of ' + CATEGORIES.join(', '));
const pointText = str(body.point_text);
if (category !== 'additional' && !pointText) return reject('point_text is required');
const count = Number(body.count);
if (!Number.isInteger(count) || count < 1 || count > 5) return reject('count must be 1-5');
const maxChars = Number(body.max_chars);
if (!Number.isInteger(maxChars) || maxChars < 60 || maxChars > 600) return reject('max_chars must be 60-600');
const p = body.participant;
if (!p || typeof p !== 'object') return reject('participant is required');
const role = ['HCP', 'NP', 'PA'].includes(str(p.role_type)) ? str(p.role_type) : 'HCP';
const reception = str(body.reception) || null;

const context = {
  category: str(body.category_label) || category,
  talking_point: pointText || null,
  reception_picked_by_rep: reception,
  points_already_covered_on_this_call: (Array.isArray(body.other_points) ? body.other_points : []).map(str).filter(Boolean).slice(0, 12),
  participant: {
    role,
    decile: p.decile, tier: str(p.tier_name), segment: str(p.segment_short_name),
    competitive_focus: str(p.competitive_focus_label), hs_patients_12_months: p.hs_patients,
    povo_patients: p.povo_patients, jak_patients: p.jak_patients, povo_discussions: p.povo_discussions,
    last_call_date: str(p.last_call_date) || null,
  },
  recent_interactions: (Array.isArray(body.interactions) ? body.interactions : []).slice(0, 12)
    .map((i) => ({ date: str(i && i.date), type: str(i && i.type_label), summary: str(i && i.summary).slice(0, 300) })),
};

const tone = {
  'well received': 'The point landed well: interest, agreement or a concrete next step.',
  'moderately received': 'Partly convinced: interest with questions, conditions or a wish to see more.',
  'not well received': 'Not convinced: hesitation, doubts or a concern that is still open.',
}[reception] || 'The rep has not rated the reception yet: give a spread (one positive, one with a question, one hesitant).';

const categoryRule = {
  messaging: 'Each note says how the ' + role + ' responded to the talking point and, where natural, what they asked for or agreed to next.',
  objection: 'Each note says whether the objection was resolved or is still open, and what the ' + role + ' wants next.',
  closing: 'Each note records the commitment or follow-up the ' + role + ' agreed to (or declined) for this close.',
  additional: 'Each note covers something discussed OUTSIDE the points already covered on this call (office logistics, access and enrollment process, patient resources, follow-up planning). Do not repeat the covered points.',
}[category];

const system_prompt = [
  'You help US pharmaceutical field reps for POVO (povorcitinib), indicated for moderate-to-severe hidradenitis suppurativa (HS) in adults, write post-call notes.',
  'Predict the ' + count + ' notes this rep is most likely to write after this call, given the talking point, the participant profile, the recent interactions and the reception. The rep will pick one and edit it.',
  categoryRule,
  'Reception: ' + tone,
  'Rules for every note:',
  '- One or two short sentences, at most ' + maxChars + ' characters, at least 6 words; plain factual call-record style; the ' + count + ' notes must differ in substance.',
  '- Refer to the participant only as "' + role + '". Never name any person: no HCP, colleague, office staff or patient names (the compliance check treats a name as an identifier). No initials, ages, dates of birth, record numbers, phone numbers or emails.',
  '- Never describe a patient side effect, reaction, infection or other harm (that is an adverse event and must be reported, not noted).',
  '- No other conditions, children, pregnancy or unapproved doses; no prices, samples, coupons, discounts or gifts; no superlatives or comparisons ("best", "safer", "better than", "cures"); no profanity, slang or filler words.',
  '- No [brackets] or placeholders: each note must read as complete as-is.',
  'Answer with JSON only: {"notes": ["...", "..."]}',
].join('\n');

const user_prompt = 'Call context (JSON):\n' + JSON.stringify(context, null, 1);

return [{ json: { valid: true, system_prompt, user_prompt, count, max_chars: maxChars } }];

/* =============================================================================
 * GUARD - POVO AI Guidance, Example Notes v1
 *
 * Response is exactly one of:
 *   {ok:true,  notes:[string]}   (1..count notes)
 *   {ok:false, reason}
 *
 * A note is dropped when it is longer than max_chars, shorter than 4 words,
 * holds a [placeholder], holds an obvious PHI pattern (email, phone, SSN,
 * MRN, date of birth) or repeats another note. No note left -> ok:false.
 * The backend then re-checks each note against the 14 compliance rules.
 * ========================================================================== */
const ctx = $('Build Prompt').first().json;
const raw = $input.first().json || {};
const fail = (reason) => [{ json: { ok: false, reason: String(reason).slice(0, 200) } }];

/* The first complete {...} in the model text: tolerates code fences, prose and a
 * stray trailing brace (seen with Claude), which a strict parser rejects. */
function firstObject(s) {
  const start = s.indexOf('{');
  if (start < 0) return null;
  let depth = 0; let inStr = false; let esc = false;
  for (let i = start; i < s.length; i += 1) {
    const ch = s[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') inStr = true;
    else if (ch === '{') depth += 1;
    else if (ch === '}') { depth -= 1; if (depth === 0) return s.slice(start, i + 1); }
  }
  return null;
}

function unwrap(value) {
  let v = value;
  for (let i = 0; i < 4; i += 1) {
    if (typeof v === 'string') {
      const s = v.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
      try { v = JSON.parse(s); } catch (e) { const o = firstObject(s); if (!o) return null; try { v = JSON.parse(o); } catch (e2) { return null; } }
      continue;
    }
    if (v && typeof v === 'object' && !Array.isArray(v) && v.output !== undefined && Object.keys(v).length <= 2) { v = v.output; continue; }
    if (v && typeof v === 'object' && !Array.isArray(v) && v.text !== undefined && Object.keys(v).length === 1) { v = v.text; continue; }
    break;
  }
  return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
}

const PHI = [
  /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i,
  /(\+?1[\s.-]?)?\(?\b\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}\b/,
  /\b\d{3}-\d{2}-\d{4}\b/,
  /\b(mrn|medical record|dob|date of birth|ssn)\b/i,
  /\b\d{1,2}\/\d{1,2}\/\d{2,4}\b/,
];

const out = unwrap(raw);
if (!out) return fail('output_unreadable');
if (!Array.isArray(out.notes)) return fail('notes missing');
const seen = new Set();
const notes = [];
for (const n of out.notes) {
  if (typeof n !== 'string') continue;
  const s = n.replace(/\s+/g, ' ').trim();
  if (!s || s.length > ctx.max_chars || s.split(' ').length < 4) continue;
  if (/[\[\]]/.test(s) || PHI.some((re) => re.test(s))) continue;
  const k = s.toLowerCase();
  if (seen.has(k)) continue;
  seen.add(k);
  notes.push(s);
  if (notes.length === ctx.count) break;
}
if (!notes.length) return fail('no usable note');
return [{ json: { ok: true, notes } }];

/* MODEL FAILED
 * The LLM chain's error output: Azure OpenAI timed out, refused, or returned
 * something the Structured Output Parser could not read. Answer at once with
 * {ok:false, reason} so the screen shows no example notes well inside
 * N8N_TIMEOUT_SECONDS instead of waiting for the execution to die. */
const e = $input.first().json || {};
const err = e.error;
const msg = (err && (err.message || err.description)) || (typeof err === 'string' ? err : '') || e.message || 'model call failed';
return [{ json: { ok: false, reason: 'model_error: ' + String(msg).replace(/\s+/g, ' ').slice(0, 180) } }];

/* REJECT REQUEST
 * The request broke the webhook contract (docs/ARCHITECTURE.md section 6).
 * Answer {ok:false, reason}; the screen shows no example notes. */
const r = $input.first().json || {};
return [{ json: { ok: false, reason: 'invalid_request: ' + String(r.reason || 'unknown').slice(0, 180) } }];
